def minPath(grid, k):
    n = len(grid)
    if k == 1:
        return [1]

    pos = {}
    for r in range(n):
        for c in range(n):
            pos[grid[r][c]] = (r, c)

    # The minimum path of length k will always start with 1.
    # To make it lexicographically smallest, we want the second element
    # to be the smallest possible neighbor of 1.
    # If k is odd, the path will alternate between the smallest neighbor and 1.
    # If k is even, the path will alternate between 1 and the smallest neighbor.

    r, c = pos[1]
    neighbors = []
    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < n and 0 <= nc < n:
            neighbors.append(grid[nr][nc])

    min_neighbor = min(neighbors)

    res = []
    for i in range(k):
        if i % 2 == 0:
            res.append(1)
        else:
            res.append(min_neighbor)

    return res

